import { character as c, type EntitySeed } from "../types";

export const primordials: EntitySeed[] = [
  c("chaos", "Chaos", "primordial", "🌌", "The Yawning Void", "x", { aliases: ["Khaos"], domains: ["the void", "the primeval gap"], summary: "The first thing to come into being in Hesiod's [[theogony|Theogony]]: the yawning gap from which the cosmos emerged. Chaos produced [[erebus]] and [[nyx]] without a partner, and is more a primeval condition than a personality; no myths of action are told about it." }),
  c("gaia", "Gaia", "primordial", "🌍", "Mother Earth", "f", { aliases: ["Gaea", "Ge", "Terra", "Tellus"], domains: ["earth", "fertility", "oaths"], summary: "The Earth personified, second being to emerge after Chaos and the ancestor of nearly every god and monster. She bore [[uranus]] and with him the Titans, Cyclopes and Hundred-Handers, then armed her son Cronus against him. She later raised the Giants and [[typhon]] against the Olympians, and was said to be the first holder of the oracle at Delphi." }),
  c("uranus", "Uranus", "primordial", "🌠", "Father Sky", "m", { aliases: ["Ouranos", "Caelus"], domains: ["sky", "the heavens"], summary: "The starry Sky, son and consort of [[gaia]] and first ruler of the cosmos. He fathered the Titans, Cyclopes and Hundred-Handers but confined his children within the earth, until Cronus castrated him with an adamantine sickle. From his blood sprang the Erinyes, the Giants and the ash-tree nymphs; from the severed parts cast into the sea, Aphrodite." }),
  c("tartarus", "Tartarus", "primordial", "🕳️", "The Abyss", "m", { aliases: ["Tartaros"], domains: ["the abyss", "the cosmic prison"], summary: "Both a primordial deity and a place: the pit lying as far beneath the earth as the sky is above it, where a bronze anvil would fall nine days to reach the bottom. The defeated Titans are imprisoned there behind bronze gates guarded by the Hundred-Handers. By [[gaia]], Tartarus fathered the monster [[typhon]]." }),
  c("eros", "Eros", "primordial", "💘", "God of Love and Desire", "m", { aliases: ["Cupid", "Amor"], domains: ["desire", "love", "procreation"], summary: "God of love and desire. In Hesiod he is among the first beings to exist, the force that makes generation possible; in later poets he is the winged, arrow-bearing son of [[aphrodite]], usually by Ares. His best-known story, told by Apuleius, is his marriage to the mortal [[psyche]]." }),
  c("nyx", "Nyx", "primordial", "🌑", "Goddess of Night", "f", { aliases: ["Nox"], domains: ["night"], summary: "Night personified, daughter of Chaos. With [[erebus]] she bore Aether and Hemera, and alone she produced a long brood of grim abstractions, among them Thanatos, Hypnos, the Moirai, Nemesis and Eris. In the [[iliad|Iliad]] even Zeus declines to anger her, abandoning his pursuit of Hypnos when the god takes refuge with his mother." }),
  c("erebus", "Erebus", "primordial", "🌫️", "God of Darkness", "m", { aliases: ["Erebos"], domains: ["darkness", "the underworld gloom"], summary: "Darkness personified, born of Chaos alongside his sister [[nyx]]. By her he fathered their bright opposites, [[aether]] and [[hemera]]. His name was also used for the gloomy region through which the dead pass on their way to the realm of Hades." }),
  c("aether", "Aether", "primordial", "✨", "The Bright Upper Air", "m", { aliases: ["Aither"], domains: ["light", "upper air"], summary: "The bright upper air that the gods breathe, as distinct from the heavier air near the earth. In Hesiod he is the son of [[erebus]] and [[nyx]] and brother of [[hemera]]. He plays a larger role in Orphic cosmogonies, where he is among the first principles of the universe." }),
  c("hemera", "Hemera", "primordial", "🌅", "Goddess of Day", "f", { aliases: ["Dies"], domains: ["day", "daylight"], summary: "Day personified, daughter of [[erebus]] and [[nyx]] and sister of [[aether]]. Hesiod describes her and her mother passing each other at the bronze threshold of Tartarus, one going out over the earth as the other comes home. Later writers often merge her with Eos, the dawn." }),
  c("pontus", "Pontus", "primordial", "🌊", "The Deep Sea", "m", { aliases: ["Pontos"], domains: ["sea"], summary: "The Sea personified, borne by [[gaia]] without a father. With her he fathered the oldest sea deities: [[nereus]], Thaumas, Phorcys, Ceto and Eurybia. He has almost no mythology of his own and serves chiefly as the ancestor of marine gods and monsters." }),
  c("ourea", "Ourea", "primordial", "⛰️", "The Mountains", "x", { aliases: ["Montes"], domains: ["mountains"], summary: "The Mountains, offspring of [[gaia]] alone, described by Hesiod as the pleasant haunts of the nymphs. Each major peak, such as Olympus, Helicon, Cithaeron and Etna, was imagined to have its own ancient god, though they seldom appear as characters in myth." }),
  c("thalassa", "Thalassa", "primordial", "🐚", "Spirit of the Sea", "f", { aliases: ["Thalatta", "Mare"], domains: ["sea"], summary: "A personification of the sea, in particular the Mediterranean. Late sources make her the daughter of [[aether]] and [[hemera]] and the consort of [[pontus]], by whom she bore the fish and, in some accounts, the Telchines. She appears in Aesop's fables and in Roman-era mosaics more often than in early myth." }),
  c("ananke", "Ananke", "primordial", "🧷", "Goddess of Necessity", "f", { aliases: ["Necessitas"], domains: ["necessity", "compulsion", "fate"], summary: "Necessity personified, the force to which even the gods must yield. In Orphic cosmogony she emerged at the beginning entwined with [[chronos]], and together they encircled the cosmic egg. Plato's Republic makes her mother of the Moirai and places the spindle of the cosmos on her knees." }),
  c("chronos", "Chronos", "primordial", "⏳", "Primordial Time", "m", { aliases: ["Khronos", "Aion"], domains: ["time"], summary: "Time personified in Orphic cosmogony, a serpentine being who, with [[ananke]], produced Aether, Chaos and the cosmic egg from which [[phanes]] hatched. He is distinct from the Titan [[cronus]], although ancient authors frequently conflated the two on the strength of their similar names." }),
  c("phanes", "Phanes", "primordial", "🥚", "The First-Born", "x", { aliases: ["Protogonos", "Erikepaios"], domains: ["creation", "light", "procreation"], summary: "The radiant, golden-winged creator god of the Orphic tradition, hatched from the cosmic egg and called Protogonos, 'first-born'. Often described as both male and female, Phanes was the first ruler of the universe, passing the sceptre to [[nyx]]; Zeus later swallowed him to absorb his power. He is unknown to Hesiod and Homer." }),
];

export const titans: EntitySeed[] = [
  c("cronus", "Cronus", "titan", "🌾", "King of the Titans", "m", { aliases: ["Kronos", "Cronos", "Saturn"], domains: ["kingship", "harvest", "the Golden Age"], summary: "Youngest of the Titans, son of [[uranus]] and [[gaia]]. He castrated his father with an adamantine sickle and ruled during the Golden Age, but swallowed each of his children by [[rhea]] to forestall a prophecy that one would overthrow him. Zeus, saved by a substituted stone, forced him to disgorge them and defeated him in the Titanomachy." }),
  c("rhea", "Rhea", "titan", "🦁", "Mother of the Gods", "f", { aliases: ["Rheia", "Ops"], domains: ["motherhood", "fertility", "mountains"], summary: "Titaness, daughter of Uranus and Gaia, sister-wife of [[cronus]] and mother of Hestia, Demeter, Hera, Hades, Poseidon and Zeus. She saved the infant Zeus by hiding him on Crete and giving Cronus a swaddled stone to swallow instead. She was later identified with the Phrygian mother goddess Cybele." }),
  c("oceanus", "Oceanus", "titan", "🌀", "The World-Encircling River", "m", { aliases: ["Okeanos"], domains: ["the world river", "fresh water"], summary: "Eldest of the Titans and god of the great river believed to encircle the earth, the source of all rivers, springs and wells. With his sister-wife [[tethys]] he fathered the three thousand river gods and three thousand Oceanids. He took no part in the war against Zeus and kept his place afterwards." }),
  c("tethys", "Tethys", "titan", "💧", "Mother of Rivers", "f", { domains: ["fresh water", "nursing"], summary: "Titaness, daughter of Uranus and Gaia and wife of [[oceanus]], by whom she bore the river gods and the [[oceanids|Oceanids]]. In the Iliad she and Oceanus fostered Hera during the Titanomachy. She is not to be confused with the Nereid Thetis, mother of Achilles." }),
  c("hyperion", "Hyperion", "titan", "🔆", "The High One", "m", { domains: ["heavenly light", "watching from above"], summary: "Titan of heavenly light, son of Uranus and Gaia. With his sister [[theia]] he fathered the three celestial luminaries: [[helios]] the sun, [[selene]] the moon and Eos the dawn. Homer sometimes uses his name as a title of Helios himself." }),
  c("theia", "Theia", "titan", "💎", "Lady of Sight and Shining", "f", { aliases: ["Thea", "Euryphaessa"], domains: ["sight", "brilliance", "the shining sky"], summary: "Titaness of sight and of the bright sky, daughter of Uranus and Gaia. By her brother [[hyperion]] she was mother of Helios, Selene and Eos. Pindar credits her with giving gold and silver their lustre and value." }),
  c("coeus", "Coeus", "titan", "🧭", "Titan of the Axis of Heaven", "m", { aliases: ["Koios", "Polus"], domains: ["intellect", "the celestial axis"], summary: "Titan son of Uranus and Gaia, whose name suggests questioning or intelligence. By his sister [[phoebe]] he fathered [[leto]] and [[asteria]], making him grandfather of Apollo, Artemis and Hecate. He was cast into Tartarus with the other Titans after their defeat." }),
  c("phoebe", "Phoebe", "titan", "🔮", "The Bright One", "f", { aliases: ["Phoibe"], domains: ["prophecy", "brightness"], summary: "Titaness, daughter of Uranus and Gaia and wife of [[coeus]], by whom she bore Leto and Asteria. According to Aeschylus she was the third holder of the oracle at [[delphi]], after Gaia and Themis, and gave it as a birthday gift to her grandson Apollo, who took the name Phoebus from her." }),
  c("crius", "Crius", "titan", "🐏", "Titan of the Constellations", "m", { aliases: ["Krios", "Kreios"], domains: ["constellations"], summary: "One of the twelve Titans, son of Uranus and Gaia. He married his half-sister [[eurybia]], daughter of Pontus, and fathered Astraeus, Pallas and Perses. Little else is recorded of him beyond his imprisonment in Tartarus after the Titanomachy." }),
  c("iapetus", "Iapetus", "titan", "🏺", "Father of Prometheus", "m", { aliases: ["Iapetos", "Japetus"], domains: ["mortality"], summary: "Titan son of Uranus and Gaia, best known for his sons by the Oceanid [[clymene]] (or Asia): [[atlas]], [[prometheus]], Epimetheus and Menoetius. Through Prometheus he was regarded as an ancestor of the human race. Homer names him alongside Cronus as a prisoner in Tartarus." }),
  c("themis", "Themis", "titan", "⚖️", "Goddess of Divine Law", "f", { aliases: ["Justitia"], domains: ["divine law", "custom", "prophecy", "assemblies"], summary: "Titaness of divine law, right custom and good counsel, daughter of Uranus and Gaia. As the second wife of Zeus she bore the [[horae|Horae]] and, in one account, the [[moirai|Moirai]]. She held the Delphic oracle before Apollo, and it was she who warned that the son of Thetis would be greater than his father." }),
  c("mnemosyne", "Mnemosyne", "titan", "🧠", "Goddess of Memory", "f", { aliases: ["Moneta"], domains: ["memory", "remembrance", "language"], summary: "Titaness of memory, daughter of Uranus and Gaia. Zeus lay with her for nine consecutive nights in Pieria, and she bore the nine [[muses|Muses]]. In Orphic belief the initiated dead were told to drink from her pool in the underworld rather than from Lethe, the water of forgetting." }),
  c("prometheus", "Prometheus", "titan", "🔥", "Forethought, Benefactor of Mankind", "m", { domains: ["forethought", "fire", "craft"], summary: "Titan son of [[iapetus]], whose name means 'forethought'. He tricked Zeus over the division of sacrifice and stole fire for mortals; in some accounts he also shaped humanity from clay. Zeus chained him in the [[caucasus|Caucasus]], where an eagle ate his ever-regenerating liver each day until [[heracles]] shot the bird and freed him." }),
  c("epimetheus", "Epimetheus", "titan", "🤦", "Afterthought", "m", { domains: ["hindsight"], summary: "Titan son of [[iapetus]] and brother of [[prometheus]], whose name means 'afterthought'. Ignoring his brother's warning never to accept a gift from Zeus, he took [[pandora]] as his wife, and so brought evils upon mankind. Their daughter Pyrrha survived the great flood with Deucalion." }),
  c("atlas", "Atlas", "titan", "🏋️", "Bearer of the Heavens", "m", { domains: ["endurance", "astronomy"], summary: "Titan son of [[iapetus]], condemned after the Titanomachy to hold up the sky at the western edge of the world. He was father of the Pleiades, the Hyades, Calypso and, in some accounts, the Hesperides. When [[heracles]] briefly took his burden in exchange for the golden apples, Atlas had to be tricked into resuming it." }),
  c("menoetius", "Menoetius", "titan", "💢", "Titan of Rash Anger", "m", { aliases: ["Menoitios"], domains: ["violent anger", "rash action"], summary: "Son of [[iapetus]] and brother of Prometheus, Epimetheus and Atlas. Hesiod calls him insolent and says Zeus struck him with a thunderbolt and sent him down to Erebus for his reckless pride and excessive strength. He is distinct from Menoetius the Argonaut, father of Patroclus." }),
  c("helios", "Helios", "titan", "☀️", "God of the Sun", "m", { aliases: ["Sol", "Helius"], domains: ["sun", "sight", "oaths"], summary: "The Sun personified, son of [[hyperion]] and [[theia]], who drives a four-horse chariot across the sky each day and sails back by night in a golden cup. All-seeing, he revealed Aphrodite's affair to Hephaestus and Persephone's abduction to Demeter. He was father of Aeetes, Circe, Pasiphae and the ill-fated Phaethon; Rhodes was his particular island." }),
  c("selene", "Selene", "titan", "🌙", "Goddess of the Moon", "f", { aliases: ["Luna", "Mene"], domains: ["moon"], summary: "The Moon personified, daughter of [[hyperion]] and [[theia]], who crosses the night sky in a chariot. Her best-known myth is her love for the shepherd Endymion, granted eternal sleep on Mount Latmus, by whom she had fifty daughters. She was later identified with [[artemis]] and Hecate." }),
  c("eos", "Eos", "titan", "🌄", "Rosy-Fingered Dawn", "f", { aliases: ["Aurora"], domains: ["dawn"], summary: "Goddess of the dawn, daughter of [[hyperion]] and [[theia]], who rises each morning from the stream of Oceanus. By [[astraeus]] she bore the winds and the stars. She carried off several mortal lovers, among them Tithonus, for whom she obtained immortality but forgot to ask eternal youth; their son was Memnon." }),
  c("leto", "Leto", "titan", "🦢", "Mother of Apollo and Artemis", "f", { aliases: ["Latona"], domains: ["motherhood", "modesty"], summary: "Daughter of the Titans [[coeus]] and [[phoebe]], and mother by Zeus of [[apollo]] and Artemis. Pursued by Hera's jealousy, she could find no land willing to receive her until the floating island of Delos allowed her to give birth. Her children fiercely defended her honour, as Niobe and Tityus discovered." }),
  c("asteria", "Asteria", "titan", "🌟", "Goddess of Falling Stars", "f", { domains: ["falling stars", "night oracles"], summary: "Daughter of [[coeus]] and [[phoebe]], sister of Leto, and mother of [[hecate]] by Perses. To escape the pursuit of Zeus she turned into a quail and threw herself into the sea, becoming the wandering island later called Delos, which sheltered her sister at the birth of Apollo." }),
  c("astraeus", "Astraeus", "titan", "🌬️", "Father of Winds and Stars", "m", { aliases: ["Astraios"], domains: ["dusk", "stars", "winds"], summary: "Second-generation Titan, son of [[crius]] and [[eurybia]]. By [[eos]], the dawn, he fathered the winds Boreas, Zephyrus and Notus, as well as the Morning Star and the other stars of heaven. Some late sources also make him father of Astraea, the star-maiden of justice." }),
  c("pallas", "Pallas", "titan", "🛡️", "Titan of Warcraft", "m", { domains: ["warcraft"], summary: "Son of [[crius]] and [[eurybia]]. By the Oceanid [[styx]] he fathered Nike, Kratos, Bia and Zelus, the four attendants of Zeus. One tradition says Athena killed him in the war with the Titans and took his skin for her aegis, a story also told of a Giant of the same name." }),
  c("perses", "Perses", "titan", "💥", "The Destroyer", "m", { domains: ["destruction"], summary: "Son of [[crius]] and [[eurybia]], described by Hesiod as pre-eminent in wisdom. He married [[asteria]] and was father of Hecate. He should not be confused with Perses the son of Perseus, or with Perses the brother of Aeetes." }),
  c("metis", "Metis", "titan", "🦉", "Goddess of Cunning Counsel", "f", { domains: ["wisdom", "cunning", "counsel"], summary: "Oceanid, daughter of Oceanus and Tethys, and the first wife of [[zeus]]; she supplied the drug that made Cronus disgorge his children. Warned that she would bear a son mightier than his father, Zeus swallowed her while she was pregnant. Her daughter [[athena]] was subsequently born from his head, and Metis continued to counsel him from within." }),
  c("dione", "Dione", "titan", "🕊️", "The Divine One", "f", { domains: ["the oracle of Dodona"], summary: "A goddess variously described as a Titaness, an Oceanid or a daughter of Atlas. In the Iliad she is the mother of [[aphrodite]] by Zeus and comforts her daughter after Diomedes wounds her. She was worshipped beside Zeus at the ancient oracle of Dodona; her name is simply the feminine form of his." }),
  c("eurynome", "Eurynome", "titan", "🐟", "Mother of the Graces", "f", { domains: ["water meadows", "pasture"], summary: "Oceanid, daughter of Oceanus and Tethys, and the third consort of Zeus, to whom she bore the [[charites|Charites]]. Together with [[thetis]] she sheltered the infant [[hephaestus]] for nine years after he was thrown from Olympus. Pausanias records a sanctuary at Phigalia where her image was half woman, half fish." }),
  c("clymene", "Clymene", "titan", "🫧", "Oceanid of Renown", "f", { aliases: ["Asia", "Klymene"], domains: ["fame", "renown"], summary: "Oceanid who, according to Hesiod, married the Titan [[iapetus]] and bore Atlas, Menoetius, Prometheus and Epimetheus; Apollodorus gives the same role to her sister Asia. Another Oceanid of this name, perhaps the same, was mother of Phaethon by [[helios]]." }),
  c("styx", "Styx", "titan", "🖤", "Goddess of the River of Oaths", "f", { domains: ["oaths", "hatred", "the river Styx"], summary: "Eldest of the Oceanids and goddess of the underworld river that bears her name. By [[pallas]] she bore Nike, Kratos, Bia and Zelus, and she was the first to bring them to the side of Zeus in the Titanomachy. In reward he made her waters the binding oath of the gods; a god who swore falsely lay breathless for a year and was exiled for nine more." }),
  c("eurybia", "Eurybia", "titan", "🪨", "Goddess of Mastery over the Sea", "f", { domains: ["mastery of the sea"], summary: "Daughter of [[pontus]] and [[gaia]], said by Hesiod to have a heart of flint. She married the Titan [[crius]] and bore Astraeus, Pallas and Perses. Her name means 'wide force', and she seems to represent power over the sea and its winds and seasons." }),
];

export const olympians: EntitySeed[] = [
  c("zeus", "Zeus", "olympian", "⚡", "King of the Gods", "m", { aliases: ["Jupiter", "Jove", "Dias"], domains: ["sky", "thunder", "law", "kingship", "hospitality", "oaths"], summary: "King of the gods and ruler of [[mount-olympus|Olympus]], god of the sky, thunder, law and hospitality. The youngest son of [[cronus]] and [[rhea]], he was hidden on Crete as an infant, forced his father to disgorge his siblings, and led them to victory in the Titanomachy, afterwards taking the heavens as his share. Married to his sister Hera, he fathered many gods and heroes by goddesses and mortal women alike, including Athena, Apollo, Artemis, Hermes, Dionysus, Perseus and Heracles. His weapon is the thunderbolt; his emblems are the eagle and the oak." }),
  c("hera", "Hera", "olympian", "🦚", "Queen of the Gods", "f", { aliases: ["Juno", "Here"], domains: ["marriage", "queenship", "women", "childbirth"], summary: "Queen of the gods and goddess of marriage, women and childbirth, daughter of Cronus and Rhea and both sister and wife of [[zeus]]. She was mother of Ares, Hebe, Eileithyia and, in some accounts alone, Hephaestus. Myth dwells on her persecution of Zeus's lovers and their children, above all [[heracles]], and on her support for the Greeks at Troy and for Jason. Her chief sanctuaries were at Argos and Samos; the peacock and the cow were sacred to her." }),
  c("poseidon", "Poseidon", "olympian", "🔱", "Earth-Shaker", "m", { aliases: ["Neptune"], domains: ["sea", "earthquakes", "horses", "storms"], summary: "God of the sea, earthquakes and horses, son of Cronus and Rhea. When the three brothers divided the cosmos by lot he received the sea, which he rules with his trident alongside his wife [[amphitrite]]. He lost the patronage of Athens to [[athena]], built the walls of Troy for Laomedon, and pursued [[odysseus]] for ten years for blinding his son Polyphemus. His children include Triton, Theseus in some accounts, and the horses Pegasus and Arion." }),
  c("demeter", "Demeter", "olympian", "🌾", "Goddess of the Grain", "f", { aliases: ["Ceres", "Deo"], domains: ["agriculture", "grain", "harvest", "the seasons", "the Mysteries"], summary: "Goddess of grain, agriculture and the fertility of the earth, daughter of Cronus and Rhea. When Hades carried off her daughter [[persephone]], she wandered the earth in grief and withheld the crops until Zeus arranged the girl's return for part of each year, the myth behind the cycle of seasons. At Eleusis she founded her Mysteries and sent [[triptolemus]] to teach mankind the cultivation of grain." }),
  c("athena", "Athena", "olympian", "🦉", "Goddess of Wisdom and War", "f", { aliases: ["Minerva", "Pallas Athena", "Athene"], domains: ["wisdom", "strategy", "warfare", "weaving", "crafts", "cities"], summary: "Virgin goddess of wisdom, strategic warfare and crafts, and patron of [[athens]]. She sprang fully armed from the head of Zeus after he swallowed her pregnant mother [[metis]]. She won Athens from Poseidon with the gift of the olive tree, and was the constant protector of heroes such as Perseus, Heracles, Diomedes and [[odysseus]]. Her attributes are the aegis, the owl and the olive; the Parthenon was her temple." }),
  c("apollo", "Apollo", "olympian", "🎵", "The Far-Shooter", "m", { aliases: ["Phoebus", "Apollon"], domains: ["prophecy", "music", "healing", "plague", "archery", "light"], summary: "God of prophecy, music, poetry, archery, healing and plague, son of Zeus and [[leto]] and twin brother of [[artemis]], born on Delos. As a youth he killed the serpent Python and took possession of the oracle at [[delphi]], the most authoritative in Greece. He leads the Muses with his lyre and fathered Asclepius and Orpheus in some accounts. His loves, including Daphne, Hyacinthus, Coronis and Cassandra, mostly ended in misfortune." }),
  c("artemis", "Artemis", "olympian", "🏹", "Goddess of the Hunt", "f", { aliases: ["Diana", "Cynthia"], domains: ["the hunt", "wilderness", "wild animals", "the moon", "maidens", "childbirth"], summary: "Virgin goddess of the hunt, wild animals and the wilderness, and protector of girls and women in childbirth. Daughter of Zeus and [[leto]], she was born just before her twin [[apollo]] and, in some versions, helped deliver him. She roams the mountains with her nymphs and punishes offences sharply: [[actaeon]] was turned into a stag for seeing her bathe, and she demanded Iphigenia's sacrifice at Aulis. She was later identified with the moon." }),
  c("ares", "Ares", "olympian", "🗡️", "God of War", "m", { aliases: ["Mars", "Enyalius"], domains: ["war", "battle-lust", "courage"], summary: "God of war in its violent and destructive aspect, son of Zeus and Hera. In Homer he is disliked even by his father, sides with the Trojans, and is wounded by the mortal Diomedes with Athena's help. His long affair with [[aphrodite]], exposed when Hephaestus trapped the pair in a net, produced Phobos, Deimos, Harmonia and, in some accounts, Eros. He was honoured chiefly in Thrace and Sparta, and as Mars was far more important to the Romans." }),
  c("aphrodite", "Aphrodite", "olympian", "🐚", "Goddess of Love and Beauty", "f", { aliases: ["Venus", "Cytherea", "Cypris"], domains: ["love", "beauty", "desire", "procreation"], summary: "Goddess of love, beauty and desire. Hesiod says she rose from the sea foam near Cyprus after the castration of [[uranus]]; Homer makes her the daughter of Zeus and Dione. Though married to Hephaestus, she loved Ares, the mortal Anchises, by whom she bore [[aeneas]], and the beautiful Adonis. By promising Helen to Paris she won the golden apple in the [[judgement-of-paris|Judgement of Paris]], setting the Trojan War in motion." }),
  c("hephaestus", "Hephaestus", "olympian", "🔨", "God of the Forge", "m", { aliases: ["Vulcan", "Hephaistos"], domains: ["forge", "fire", "metalworking", "craftsmanship", "volcanoes"], summary: "God of fire, the forge and craftsmanship, son of Hera, by Zeus or by her alone. Born lame, he was thrown from Olympus and landed in the sea or on Lemnos, returning later to become the smith of the gods. He made the [[armor-of-achilles|armour of Achilles]], the aegis, golden automata, and Pandora, and split Zeus's skull for the birth of Athena. His wife was Aphrodite, or in the Iliad the Grace Aglaea." }),
  c("hermes", "Hermes", "olympian", "🪽", "Messenger of the Gods", "m", { aliases: ["Mercury", "Argeiphontes"], domains: ["travel", "trade", "thieves", "heralds", "boundaries", "guiding souls"], summary: "Herald and messenger of the gods, patron of travellers, merchants, thieves and herdsmen, and guide of souls to the underworld. Son of Zeus and the Pleiad [[maia]], born on Mount Cyllene, he invented the lyre from a tortoise shell on his first day and stole the cattle of [[apollo]], then traded the lyre for forgiveness. He wears winged sandals, carries the [[caduceus]], and killed the hundred-eyed Argus to free Io." }),
  c("hestia", "Hestia", "olympian", "🏠", "Goddess of the Hearth", "f", { aliases: ["Vesta"], domains: ["hearth", "home", "family", "the sacrificial flame"], summary: "Virgin goddess of the hearth, the home and the sacrificial fire. The first-born child of Cronus and Rhea, she was the first swallowed and the last disgorged. She refused the suits of Poseidon and Apollo and swore perpetual virginity, and Zeus granted her a place at the centre of every house and the first share of every sacrifice. She has almost no myths, but her cult was present at every household and civic hearth." }),
  c("dionysus", "Dionysus", "olympian", "🍇", "God of Wine and Ecstasy", "m", { aliases: ["Bacchus", "Liber", "Bromios", "Iacchus"], domains: ["wine", "ecstasy", "theatre", "vegetation", "ritual madness"], summary: "God of wine, ecstasy, theatre and ritual madness, son of Zeus and the Theban princess [[semele]]. When Semele was consumed by the sight of Zeus in his full glory, the unborn child was sewn into his father's thigh and born a second time, hence 'twice-born'. He wandered as far as India spreading the vine, accompanied by maenads and satyrs, punished those who denied him such as [[pentheus]], and married [[ariadne]] on Naxos." }),
];

export const otherGods: EntitySeed[] = [
  c("hades", "Hades", "underworld god", "💀", "Lord of the Dead", "m", { aliases: ["Pluto", "Plouton", "Aidoneus", "Dis Pater"], domains: ["the dead", "the underworld", "wealth of the earth"], summary: "Ruler of the [[underworld]] and of the dead, eldest son of Cronus and Rhea. In the division of the cosmos by lot he received the realm below, which came to share his name. Stern and unyielding rather than evil, he seldom leaves his kingdom; his one famous venture was the abduction of [[persephone]] to be his queen. He owns the [[helm-of-darkness|helm of invisibility]], and as Plouton was honoured as giver of the earth's wealth." }),
  c("persephone", "Persephone", "underworld god", "🌸", "Queen of the Underworld", "f", { aliases: ["Kore", "Proserpina", "Persephassa"], domains: ["the dead", "spring", "vegetation", "the Mysteries"], summary: "Daughter of Zeus and [[demeter]] and queen of the underworld. [[hades]] carried her off as she gathered flowers; because she ate pomegranate seeds in his realm, she must spend part of every year below, and her return each spring brings the renewal of the crops. With her mother she was worshipped in the Eleusinian Mysteries. As queen of the dead she receives Orpheus, Heracles and Odysseus." }),
  c("hecate", "Hecate", "underworld god", "🗝️", "Goddess of the Crossroads", "f", { aliases: ["Hekate", "Trivia"], domains: ["magic", "crossroads", "ghosts", "night", "necromancy"], summary: "Goddess of magic, crossroads, night and ghosts, daughter of the Titans Perses and [[asteria]]. Hesiod praises her at length as honoured by Zeus with a share in earth, sea and sky. She carried torches in the search for [[persephone]] and became her companion in the underworld. Later tradition shows her in triple form, attended by hounds, and as patron of sorceresses such as [[medea]]." }),
  c("pan", "Pan", "rustic god", "🐐", "God of the Wild", "m", { aliases: ["Faunus", "Inuus"], domains: ["shepherds", "flocks", "wilderness", "rustic music", "panic"], summary: "Goat-legged, horned god of shepherds, flocks and wild places, native to Arcadia and usually called a son of [[hermes]]. He pursued the nymph [[syrinx]], who became the reeds from which he made his pipes. The sudden terror felt in lonely places, 'panic', takes its name from him; the Athenians credited him with routing the Persians at Marathon." }),
  c("hebe", "Hebe", "god", "🥂", "Goddess of Youth", "f", { aliases: ["Juventas", "Ganymeda"], domains: ["youth", "the prime of life"], summary: "Goddess of youth, daughter of Zeus and Hera. She served the gods as cupbearer, pouring their nectar, until [[ganymede]] took over the office. When [[heracles]] was received on Olympus after his death she became his wife, sealing his reconciliation with her mother." }),
  c("eileithyia", "Eileithyia", "god", "🤰", "Goddess of Childbirth", "f", { aliases: ["Ilithyia", "Lucina"], domains: ["childbirth", "labour pains"], summary: "Goddess of childbirth and labour, daughter of Zeus and [[hera]], with an ancient cult in a cave at Amnisos on Crete. At Hera's bidding she could delay a birth, as she did for nine days with [[leto]] and again with [[alcmene]], postponing the arrival of Heracles so that Eurystheus would be born first." }),
  c("amphitrite", "Amphitrite", "sea god", "🐬", "Queen of the Sea", "f", { aliases: ["Salacia"], domains: ["sea", "sea creatures"], summary: "Sea goddess and wife of [[poseidon]], a Nereid according to Hesiod or an Oceanid according to Apollodorus. She at first fled his courtship and hid near Atlas, until a dolphin found her and persuaded her to return. She bore [[triton]], Rhode and Benthesikyme, and in Homer is little more than a name for the sea itself." }),
  c("triton", "Triton", "sea god", "📯", "Herald of the Sea", "m", { domains: ["waves", "the sea's herald"], summary: "Son of [[poseidon]] and [[amphitrite]], usually shown as a man above the waist and a fish below. He calms or raises the waves by blowing a conch-shell trumpet. He guided the [[argonauts|Argonauts]] from Lake Tritonis back to the sea. Later art multiplied him into a whole race of Tritons escorting the sea gods." }),
  c("nereus", "Nereus", "sea god", "🧓", "The Old Man of the Sea", "m", { domains: ["sea", "truth", "prophecy"], summary: "Eldest son of [[pontus]] and [[gaia]], an ancient sea god praised by Hesiod as truthful and gentle. With the Oceanid Doris he fathered the fifty [[nereids|Nereids]], among them Thetis and Amphitrite. A shape-shifting prophet, he was seized by Heracles and held fast until he revealed the way to the garden of the Hesperides." }),
  c("proteus", "Proteus", "sea god", "🦭", "The Shape-Shifting Prophet", "m", { domains: ["sea", "prophecy", "shape-shifting", "seals"], summary: "A prophetic old sea god and herdsman of Poseidon's seals, living on the island of Pharos off Egypt. He knows all things but answers only those who can hold him while he changes through every shape. In the [[odyssey|Odyssey]], [[menelaus]] does so, with the help of Proteus's daughter Eidothea, to learn how to get home. His name gives the word 'protean'." }),
  c("phorcys", "Phorcys", "sea god", "🦀", "Father of Sea-Monsters", "m", { aliases: ["Phorkys", "Phorcus"], domains: ["the hidden dangers of the deep"], summary: "Ancient sea god, son of [[pontus]] and [[gaia]]. With his sister [[ceto]] he produced a brood of monsters: the Graeae, the Gorgons, Echidna in some accounts, and the serpent Ladon that guarded the golden apples. Homer calls him an old man of the sea and gives him a harbour on Ithaca." }),
  c("ceto", "Ceto", "sea god", "🐋", "Mother of Sea-Monsters", "f", { aliases: ["Keto"], domains: ["sea monsters", "dangers of the sea"], summary: "Sea goddess, daughter of [[pontus]] and [[gaia]], whose name means 'sea monster' or 'whale'. By her brother [[phorcys]] she bore the Graeae, the Gorgons, the serpent Ladon and, in Hesiod's likeliest reading, Echidna. Her name survives in the word 'cetacean'." }),
  c("benthesikyme", "Benthesikyme", "sea god", "🌊", "Lady of the Deep Swells", "f", { aliases: ["Benthesicyme"], domains: ["waves"], summary: "Daughter of [[poseidon]] and [[amphitrite]], whose name means 'wave of the deep'. She lived in Ethiopia, where, according to Apollodorus, Poseidon gave her his infant son Eumolpus to raise after the child's mother Chione threw him into the sea. She is otherwise almost unknown." }),
  c("rhode", "Rhode", "sea god", "🌹", "Nymph of Rhodes", "f", { aliases: ["Rhodos"], domains: ["the island of Rhodes"], summary: "Sea nymph and eponym of the island of Rhodes, usually called a daughter of [[poseidon]] by Amphitrite or Halia. Pindar tells how [[helios]], absent when the gods divided the earth, claimed the island as it rose from the sea and took Rhode as his wife. Their seven sons, the Heliadae, were famed astronomers." }),
  c("cymopoleia", "Cymopoleia", "sea god", "🌪️", "Goddess of Storm Waves", "f", { aliases: ["Kymopoleia"], domains: ["storm waves"], summary: "A daughter of [[poseidon]], mentioned only once, in Hesiod's Theogony. Poseidon gave her in marriage to Briareus, one of the [[hecatoncheires|Hundred-Handers]], in reward for his service against the Titans. Her name means 'wave-ranger'." }),
  c("iris", "Iris", "god", "🌈", "Goddess of the Rainbow", "f", { aliases: ["Arcus"], domains: ["rainbow", "messages"], summary: "Goddess of the rainbow and messenger of the gods, daughter of the sea god Thaumas and the Oceanid Electra, and sister of the [[harpies|Harpies]]. In the Iliad she carries the commands of Zeus; in later poets she is especially the attendant of [[hera]]. Swift and golden-winged, she links heaven, earth and sea." }),
  c("harmonia", "Harmonia", "god", "🎼", "Goddess of Harmony", "f", { aliases: ["Concordia"], domains: ["harmony", "concord"], summary: "Goddess of harmony and concord, daughter of [[ares]] and [[aphrodite]]. Zeus gave her in marriage to [[cadmus]], founder of Thebes, at a wedding attended by all the gods. Her wedding gift, the necklace made by Hephaestus, brought ruin on every later owner. She and Cadmus ended their lives transformed into serpents." }),
  c("phobos", "Phobos", "spirit", "😱", "God of Fear and Rout", "m", { aliases: ["Pavor", "Terror"], domains: ["fear", "panic", "rout in battle"], summary: "Personification of fear and panic flight in battle, son of [[ares]] and [[aphrodite]] and twin of [[deimos]]. He accompanies his father into war and yokes his chariot. His image appeared on the shields of Agamemnon and Heracles, and the Spartans maintained a shrine to him." }),
  c("deimos", "Deimos", "spirit", "😨", "God of Dread", "m", { aliases: ["Formido", "Metus"], domains: ["dread", "terror"], summary: "Personification of the dread that comes before battle, son of [[ares]] and [[aphrodite]]. With his twin [[phobos]] he attends Ares on the battlefield, alongside Eris and Enyo. The two moons of the planet Mars are named after the brothers." }),
  c("boreas", "Boreas", "wind god", "❄️", "The North Wind", "m", { aliases: ["Aquilo"], domains: ["the north wind", "winter"], summary: "God of the cold north wind, son of [[astraeus]] and [[eos]], who dwells in Thrace. He carried off the Athenian princess Oreithyia and fathered the winged Argonauts [[zetes]] and Calais. The Athenians, claiming him as a kinsman by marriage, credited him with wrecking the Persian fleet off Artemisium." }),
  c("zephyrus", "Zephyrus", "wind god", "🍃", "The West Wind", "m", { aliases: ["Zephyr", "Favonius"], domains: ["the west wind", "spring"], summary: "God of the gentle west wind and herald of spring, son of [[astraeus]] and [[eos]]. By the Harpy Podarge he fathered Xanthus and Balius, the immortal horses of Achilles. In one version of the story, jealous of [[apollo]], he blew the discus that killed Hyacinthus. His wife was Chloris, goddess of flowers." }),
  c("aeolus", "Aeolus", "wind god", "💨", "Keeper of the Winds", "m", { aliases: ["Aiolos"], domains: ["winds"], summary: "Ruler of the winds, son of Hippotes, living with his six sons and six daughters on the floating, bronze-walled island of Aeolia. In the [[odyssey|Odyssey]] he gives [[odysseus]] a leather bag holding all the contrary winds; the crew opens it within sight of Ithaca, and Aeolus refuses to help a second time. Homer treats him as a mortal favoured by the gods; later writers make him a god." }),
  c("charon", "Charon", "underworld god", "🛶", "Ferryman of the Dead", "m", { aliases: ["Kharon"], domains: ["passage of the dead"], summary: "The aged ferryman of the dead, son of [[erebus]] and [[nyx]], who carries souls across the Acheron or Styx into the realm of Hades. His fare was an obol placed in the mouth of the corpse, and the unburied were left to wander the near bank. A few living passengers, including Heracles, Orpheus and Aeneas, persuaded or compelled him to take them." }),
  c("asclepius", "Asclepius", "deified mortal", "⚕️", "God of Medicine", "m", { aliases: ["Aesculapius", "Asklepios"], domains: ["medicine", "healing"], summary: "God of medicine, son of [[apollo]] and the mortal Coronis, cut from his mother's body on her funeral pyre and reared by the centaur [[chiron]]. His skill grew so great that he raised the dead, and Zeus struck him down with a thunderbolt for upsetting the natural order, afterwards placing him among the gods. His chief sanctuary was at Epidaurus; his emblem is the serpent-entwined staff." }),
  c("psyche", "Psyche", "deified mortal", "🦋", "Goddess of the Soul", "f", { domains: ["the soul"], summary: "A mortal princess whose beauty provoked the jealousy of [[aphrodite]], and the heroine of the tale told in Apuleius's Golden Ass. Married to an unseen husband, she lost him when she lit a lamp and discovered he was [[eros]]. After completing a series of impossible tasks, including a descent to the underworld, she was made immortal and reunited with him. Their daughter was Hedone, Pleasure." }),
  c("ganymede", "Ganymede", "deified mortal", "🦅", "Cupbearer of the Gods", "m", { aliases: ["Ganymedes", "Catamitus"], domains: ["cupbearing"], summary: "A Trojan prince, son of Tros, called by Homer the most beautiful of mortals. [[zeus]], in the form of an eagle or by sending one, carried him off to Olympus to serve as cupbearer of the gods, compensating his father with divine horses. He was granted immortality and was identified with the constellation Aquarius." }),
];

export const spirits: EntitySeed[] = [
  c("nike", "Nike", "spirit", "🏆", "Goddess of Victory", "f", { aliases: ["Victoria"], domains: ["victory"], summary: "Winged goddess of victory, in war and in athletic contest alike. Daughter of the Titan [[pallas]] and [[styx]], she was brought by her mother to fight beside Zeus in the Titanomachy and remained at his side thereafter. She is closely associated with [[athena]], whose great statue in the Parthenon held a Nike in its hand." }),
  c("kratos", "Kratos", "spirit", "💪", "Personification of Strength", "m", { aliases: ["Cratos", "Cratus"], domains: ["strength", "power", "sovereign rule"], summary: "Personification of strength and power, son of [[pallas]] and [[styx]] and brother of Nike, Bia and Zelus. The four siblings never leave the side of Zeus and act as his enforcers. In [[prometheus-bound|Prometheus Bound]], Kratos harshly oversees Hephaestus as he chains Prometheus to the rock." }),
  c("bia", "Bia", "spirit", "✊", "Personification of Force", "f", { aliases: ["Vis"], domains: ["force", "compulsion"], summary: "Personification of force and compulsion, daughter of [[pallas]] and [[styx]]. With her siblings Nike, [[kratos]] and Zelus she stands permanently beside the throne of Zeus. She appears as a silent character in Prometheus Bound, helping to fasten the Titan to his rock." }),
  c("zelus", "Zelus", "spirit", "🔥", "Personification of Zeal", "m", { aliases: ["Zelos", "Invidia"], domains: ["zeal", "rivalry", "emulation"], summary: "Personification of zeal, rivalry and eager emulation, son of [[pallas]] and [[styx]] and brother of Nike, Kratos and Bia. Like them, he was rewarded for joining Zeus against the Titans with a permanent place beside the god's throne. He has no independent myths." }),
  c("thanatos", "Thanatos", "spirit", "🪦", "God of Death", "m", { aliases: ["Mors", "Letum"], domains: ["death", "peaceful death"], summary: "Death personified, son of [[nyx]] and twin brother of [[hypnos]]. In the Iliad the two brothers carry the body of [[sarpedon]] home to Lycia. He could occasionally be bested: Sisyphus bound him in chains so that no one could die, and Heracles wrestled him to win back Alcestis." }),
  c("hypnos", "Hypnos", "spirit", "😴", "God of Sleep", "m", { aliases: ["Somnus"], domains: ["sleep"], summary: "Sleep personified, son of [[nyx]] and twin brother of [[thanatos]]. In the Iliad, Hera bribes him with marriage to the Grace Pasithea to put Zeus to sleep so that Poseidon can aid the Greeks; he recalls that after an earlier such favour only the protection of his mother Night saved him from Zeus's anger. Ovid places his cave beside the river Lethe." }),
  c("morpheus", "Morpheus", "spirit", "💭", "God of Dreams", "m", { domains: ["dreams", "human forms in dreams"], summary: "A god of dreams known chiefly from Ovid's [[metamorphoses|Metamorphoses]], where he is the most skilled of the thousand sons of Somnus ([[hypnos]]). He specialises in imitating human shapes, while his brothers Icelos and Phantasos take the forms of animals and inanimate things. He appears to Alcyone in the likeness of her drowned husband Ceyx." }),
  c("nemesis", "Nemesis", "spirit", "⚖️", "Goddess of Retribution", "f", { aliases: ["Rhamnousia", "Adrasteia", "Invidia"], domains: ["retribution", "righteous indignation", "balance"], summary: "Goddess of retribution, who punishes arrogance and excessive good fortune; Hesiod makes her a daughter of [[nyx]]. In the lost epic Cypria she, not Leda, was mother of [[helen]], having been pursued by Zeus through many shapes. She lured [[narcissus]] to the pool where he fell in love with his reflection. Her principal sanctuary was at Rhamnous in Attica." }),
  c("eris", "Eris", "spirit", "🍎", "Goddess of Strife", "f", { aliases: ["Discordia"], domains: ["strife", "discord", "rivalry"], summary: "Goddess of strife and discord, daughter of [[nyx]] in Hesiod and sister and companion of Ares in Homer. Left uninvited to the wedding of Peleus and Thetis, she threw among the guests the golden [[apple-of-discord|apple]] inscribed 'for the fairest', the quarrel over which led to the Trojan War. Hesiod also distinguishes a second, beneficial Eris who spurs mortals to honest competition." }),
  c("momos", "Momos", "spirit", "🙄", "God of Blame and Mockery", "m", { aliases: ["Momus"], domains: ["blame", "mockery", "criticism"], summary: "Personification of fault-finding and mockery, a son of [[nyx]]. In a fable of Aesop he criticised the handiwork of Zeus, Poseidon and Athena in turn, and was eventually expelled from Olympus for his carping. The Cypria is said to have made him the adviser who suggested the Trojan War to Zeus as a way to lighten the overburdened earth." }),
  c("oizys", "Oizys", "spirit", "😩", "Personification of Misery", "f", { aliases: ["Miseria"], domains: ["misery", "distress"], summary: "Personification of misery, woe and distress, listed by Hesiod among the children born to [[nyx]] without a father, beside Momos, the Hesperides and the Moirai. She is an abstraction without any myth or cult of her own." }),
  c("geras", "Geras", "spirit", "👴", "Personification of Old Age", "m", { aliases: ["Senectus"], domains: ["old age"], summary: "Personification of old age, a son of [[nyx]], depicted as a small, shrivelled old man. A handful of Athenian vase paintings show [[heracles]] fighting or threatening him with his club, though no literary account of the episode survives." }),
  c("apate", "Apate", "spirit", "🎭", "Personification of Deceit", "f", { aliases: ["Fraus"], domains: ["deceit", "fraud"], summary: "Personification of deceit and fraud, a daughter of [[nyx]]. In Nonnus's Dionysiaca, Hera borrows her girdle of deception in order to trick [[semele]] into asking Zeus to appear in his true form. Her male counterpart was Dolos, Trickery." }),
  c("philotes", "Philotes", "spirit", "🤗", "Personification of Affection", "f", { aliases: ["Amicitia"], domains: ["affection", "friendship", "intimacy"], summary: "Personification of affection, friendship and sexual intimacy, and one of the few benign figures among the children of [[nyx]] in Hesiod's Theogony. The philosopher Empedocles later made Philotes, Love, one of the two forces that move the cosmos, opposed to Neikos, Strife." }),
  c("moros", "Moros", "spirit", "☠️", "Personification of Doom", "m", { aliases: ["Fatum"], domains: ["doom", "destined death"], summary: "Personification of impending doom, the fate that drives a mortal towards death. Hesiod names him first among the fatherless children of [[nyx]], ahead of his siblings Ker and [[thanatos]]. In Prometheus Bound, Prometheus says he stopped mortals foreseeing their doom by giving them blind hope." }),
  c("tyche", "Tyche", "spirit", "🎲", "Goddess of Fortune", "f", { aliases: ["Fortuna"], domains: ["fortune", "chance", "prosperity of cities"], summary: "Goddess of fortune and chance, called a daughter of [[oceanus]] and Tethys by Hesiod, or of Zeus by Pindar. Her cult grew greatly in the Hellenistic period, when each city honoured its own Tyche wearing a crown of city walls; the Tyche of Antioch was the most famous. Her attributes are the rudder, the wheel and the [[cornucopia]]." }),

  c("calliope", "Calliope", "muse", "📖", "Muse of Epic Poetry", "f", { aliases: ["Kalliope"], domains: ["epic poetry", "eloquence"], summary: "Muse of epic poetry and, according to Hesiod, the foremost of the nine daughters of Zeus and [[mnemosyne]], since she attends on kings. She was mother of [[orpheus]], and in some accounts of Linus, by the Thracian king Oeagrus or by Apollo. She is shown holding a writing tablet." }),
  c("clio", "Clio", "muse", "📜", "Muse of History", "f", { aliases: ["Kleio"], domains: ["history"], summary: "Muse of history, daughter of Zeus and [[mnemosyne]]; her name comes from the verb 'to make famous'. Apollodorus says that Aphrodite, whom she had mocked for loving Adonis, caused her to fall in love with Pierus, by whom she bore Hyacinthus. Her attribute is an open scroll or a chest of books." }),
  c("erato", "Erato", "muse", "💌", "Muse of Love Poetry", "f", { domains: ["love poetry", "lyric poetry"], summary: "Muse of lyric and love poetry, daughter of Zeus and [[mnemosyne]]. Her name means 'lovely' and is related to that of Eros. Apollonius invokes her at the opening of the third book of the [[argonautica|Argonautica]], which tells of Medea's love for Jason. She is usually shown with a lyre or cithara." }),
  c("euterpe", "Euterpe", "muse", "🎶", "Muse of Music", "f", { domains: ["music", "lyric poetry", "the aulos"], summary: "Muse of music and lyric song, daughter of Zeus and [[mnemosyne]]; her name means 'giver of delight'. Her attribute is the aulos, the double pipe, which some credited her with inventing. One tradition makes her the mother of the Thracian king Rhesus by the river god Strymon." }),
  c("melpomene", "Melpomene", "muse", "🎭", "Muse of Tragedy", "f", { domains: ["tragedy"], summary: "Muse of tragedy, daughter of Zeus and [[mnemosyne]]; her name means 'the singer', and she was originally a Muse of song in general. She is depicted with a tragic mask, the high boots of the tragic actor, and sometimes a club or sword. Some sources make her the mother of the [[sirens|Sirens]] by the river god Achelous." }),
  c("polyhymnia", "Polyhymnia", "muse", "🙏", "Muse of Sacred Hymns", "f", { aliases: ["Polymnia"], domains: ["sacred hymns", "pantomime", "eloquence"], summary: "Muse of sacred hymns and, in later lists, of pantomime and eloquence; daughter of Zeus and [[mnemosyne]]. Her name means 'she of many hymns'. Artists show her veiled, cloaked and pensive, often leaning on a pillar with a finger held to her lips." }),
  c("terpsichore", "Terpsichore", "muse", "💃", "Muse of Dance", "f", { domains: ["dance", "choral song"], summary: "Muse of dance and choral song, daughter of Zeus and [[mnemosyne]]; her name means 'delighting in the dance'. She is shown seated or dancing with a lyre and plectrum. Like Melpomene, she is named in some sources as mother of the [[sirens|Sirens]] by Achelous." }),
  c("thalia", "Thalia", "muse", "😂", "Muse of Comedy", "f", { aliases: ["Thaleia"], domains: ["comedy", "pastoral poetry"], summary: "Muse of comedy and pastoral poetry, daughter of Zeus and [[mnemosyne]]; her name means 'the flourishing'. She carries a comic mask, a shepherd's crook and a wreath of ivy. Apollodorus makes her the mother of the Corybantes by Apollo. She shares her name with one of the [[charites|Graces]]." }),
  c("urania", "Urania", "muse", "🔭", "Muse of Astronomy", "f", { aliases: ["Ourania"], domains: ["astronomy", "astrology"], summary: "Muse of astronomy, daughter of Zeus and [[mnemosyne]]; her name means 'heavenly'. She is shown with a celestial globe and a pointer. Some sources make her mother of the musician Linus. Christian and Renaissance poets, Milton among them, adopted her as the patron of elevated sacred verse." }),

  c("eunomia", "Eunomia", "hora", "📏", "Goddess of Good Order", "f", { domains: ["good order", "lawful government"], summary: "Goddess of good order and lawful government, one of the three [[horae|Horae]] born to Zeus and [[themis]] in Hesiod's account. With her sisters Dike and Eirene she watches over the stability of society. The Spartan poet Tyrtaeus gave her name to a poem, and Pindar praises her as the foundation of cities." }),
  c("dike", "Dike", "hora", "⚖️", "Goddess of Justice", "f", { aliases: ["Justitia", "Astraea"], domains: ["justice", "fair judgement"], summary: "Goddess of human justice, daughter of Zeus and [[themis]] and one of the [[horae|Horae]]. Hesiod describes her sitting beside her father and reporting the crooked judgements of men. Aratus identifies her with the constellation Virgo: the last immortal to live among mortals, she withdrew to the sky in the Bronze Age." }),
  c("eirene", "Eirene", "hora", "🕊️", "Goddess of Peace", "f", { aliases: ["Pax", "Irene"], domains: ["peace", "prosperity"], summary: "Goddess of peace, daughter of Zeus and [[themis]] and one of the [[horae|Horae]]. The Athenians set up an altar to her in the fourth century BC, and a celebrated statue by Cephisodotus showed her carrying the infant Ploutos, Wealth. She is the title figure of Aristophanes' comedy Peace, hauled out of a pit by the farmers of Greece." }),

  c("clotho", "Clotho", "fate", "🧵", "The Spinner", "f", { aliases: ["Klotho", "Nona"], domains: ["the thread of life", "birth"], summary: "Youngest of the three [[moirai|Moirai]], who spins the thread of each mortal life at birth. Hesiod calls the Fates daughters of [[nyx]] in one passage and of Zeus and Themis in another. In Pindar's account of [[pelops]], it is Clotho who lifts the restored boy from the cauldron." }),
  c("lachesis", "Lachesis", "fate", "📐", "The Allotter", "f", { aliases: ["Decima"], domains: ["the allotment of life", "destiny"], summary: "The second of the [[moirai|Moirai]], who measures out the thread spun by [[clotho]] and so assigns each person a lot in life. In the myth of Er that closes Plato's Republic, the souls awaiting rebirth choose their next lives before her, and she sings of things past." }),
  c("atropos", "Atropos", "fate", "✂️", "The Inflexible", "f", { aliases: ["Aisa", "Morta"], domains: ["death", "the end of life"], summary: "Eldest of the three [[moirai|Moirai]], whose name means 'she who cannot be turned'. She fixes the manner of each mortal's death and ends life by cutting the thread spun by [[clotho]] and measured by [[lachesis]]. The plant genus Atropa, deadly nightshade, and the drug atropine are named after her." }),

  c("aglaea", "Aglaea", "grace", "💫", "Grace of Splendour", "f", { aliases: ["Aglaia", "Charis"], domains: ["splendour", "beauty", "adornment"], summary: "Youngest of the three [[charites|Charites]], daughters of Zeus and the Oceanid [[eurynome]], and goddess of splendour and radiance. Hesiod names her as the wife of [[hephaestus]], a role the Iliad gives to a Grace called simply Charis." }),
  c("euphrosyne", "Euphrosyne", "grace", "😊", "Grace of Good Cheer", "f", { aliases: ["Euthymia"], domains: ["joy", "mirth", "good cheer"], summary: "One of the three [[charites|Charites]], daughters of Zeus and [[eurynome]], and goddess of joy and merriment. With her sisters she attends Aphrodite and dances with the Muses to Apollo's lyre. Pindar says that the Graces give mortals everything that is sweet and delightful." }),
  c("thalia-grace", "Thalia (Grace)", "grace", "🌺", "Grace of Festivity", "f", { aliases: ["Thaleia"], domains: ["festivity", "abundance", "banquets"], summary: "One of the three [[charites|Charites]], daughters of Zeus and [[eurynome]], presiding over festive banquets and flourishing abundance. Her name, 'the blooming one', is shared with the Muse of comedy, [[thalia]], from whom she is distinct." }),
];

export const nymphs: EntitySeed[] = [
  c("thetis", "Thetis", "nymph", "🌊", "Silver-Footed Nereid", "f", { domains: ["sea"], summary: "Sea goddess, daughter of [[nereus]] and leader of the Nereids. Both Zeus and Poseidon courted her until a prophecy revealed that her son would be greater than his father; she was then married to the mortal [[peleus]], who had to hold her through many changes of shape. She was mother of [[achilles]], whom she tried to make immortal, and for whom she obtained new armour from Hephaestus." }),
  c("calypso", "Calypso", "nymph", "🏝️", "Nymph of Ogygia", "f", { aliases: ["Kalypso"], summary: "A nymph, daughter of [[atlas]], living alone on the remote island of [[ogygia]]; her name means 'the concealer'. In the Odyssey she rescues the shipwrecked [[odysseus]] and keeps him as her lover for seven years, offering him immortality, until Zeus sends Hermes to order his release. She then helps him build a raft." }),
  c("circe", "Circe", "nymph", "🐖", "Enchantress of Aeaea", "f", { aliases: ["Kirke"], domains: ["sorcery", "herbs and potions"], summary: "Sorceress and goddess, daughter of [[helios]] and the Oceanid Perse, sister of Aeetes and Pasiphae, living on the island of [[aeaea]]. She turned the crew of [[odysseus]] into swine; protected by the herb moly from Hermes, he compelled her to restore them, then stayed a year as her guest and lover. She also purified Jason and Medea, and in later tradition bore Odysseus a son, Telegonus." }),
  c("echo", "Echo", "nymph", "🗣️", "Nymph of Mount Cithaeron", "f", { domains: ["echoes"], summary: "A mountain nymph of Cithaeron. In Ovid's version, [[hera]] punished her for distracting her with chatter while Zeus's lovers escaped, leaving her able only to repeat the last words of others. Rejected by [[narcissus]], she wasted away until nothing but her voice remained. An older tale makes her loved by [[pan]], who had her torn apart by shepherds." }),
  c("daphne", "Daphne", "nymph", "🌿", "Nymph of the Laurel", "f", { summary: "A naiad, daughter of the river god [[peneus]] in Thessaly, or of Ladon in Arcadia, and a devoted huntress. Struck by an arrow of Eros, [[apollo]] pursued her; at the point of capture she prayed for rescue and was transformed into a laurel tree, in Greek daphne. Apollo made the laurel his sacred plant, and its leaves crowned victors at the Pythian Games." }),
  c("syrinx", "Syrinx", "nymph", "🎋", "Nymph of the Reeds", "f", { summary: "An Arcadian naiad and follower of Artemis. Fleeing the advances of [[pan]], she reached the river Ladon and begged her sister nymphs to change her shape; Pan found himself holding only marsh reeds. From reeds of unequal length joined with wax he made the pan pipes, which the Greeks called the syrinx." }),
  c("maia", "Maia", "nymph", "⭐", "Eldest of the Pleiades", "f", { domains: ["nursing", "growth"], summary: "Eldest of the seven [[pleiades|Pleiades]], daughters of [[atlas]] and Pleione, a shy nymph living in a cave on Mount Cyllene in Arcadia. There Zeus visited her in secret, and she bore [[hermes]]. She also raised Arcas, the son of Callisto. The Romans identified her with an Italian goddess of growth, for whom the month of May is named." }),
  c("callisto", "Callisto", "nymph", "🐻", "The Great Bear", "f", { aliases: ["Kallisto"], summary: "An Arcadian nymph or princess, daughter of Lycaon, and a hunting companion of [[artemis]] sworn to chastity. Zeus seduced her, in some versions disguised as Artemis herself, and she was turned into a bear by Zeus, Hera or Artemis. Zeus set her among the stars as Ursa Major. Her son Arcas was ancestor of the Arcadians." }),
  c("arethusa", "Arethusa", "nymph", "⛲", "Nymph of the Spring at Syracuse", "f", { summary: "A nymph of Elis and attendant of [[artemis]]. When the river god [[alpheus]] pursued her after she bathed in his waters, Artemis hid her in cloud and turned her into a stream that ran beneath the sea to emerge as a freshwater spring on Ortygia at Syracuse. Alpheus was said to follow, mingling his waters with hers. Her head appears on Syracusan coinage." }),
  c("eurydice", "Eurydice", "nymph", "🥀", "Wife of Orpheus", "f", { summary: "A nymph, usually called a dryad, and wife of [[orpheus]]. She died of a snakebite, in Virgil's account while fleeing the beekeeper Aristaeus. Orpheus descended to the underworld and won her release from Hades and Persephone with his music, on condition that he not look back until they reached the light; he turned too soon, and she was lost a second time." }),
  c("oenone", "Oenone", "nymph", "🍷", "Nymph of Mount Ida", "f", { summary: "A nymph of Mount Ida near Troy, daughter of the river god Cebren, skilled in prophecy and healing. She was the first wife of [[paris]], who abandoned her for [[helen]]. When he was mortally wounded by the arrows of Philoctetes she refused to cure him; repenting too late, she found him dead and took her own life." }),
  c("aegina", "Aegina", "nymph", "🏖️", "Nymph of the Island of Aegina", "f", { aliases: ["Aigina"], summary: "A naiad, daughter of the river god [[asopus]]. [[zeus]] carried her off, as an eagle or a flame, to the island of Oenone, afterwards renamed for her; [[sisyphus]] earned his punishment in part by telling her father who had taken her. She bore Aeacus, grandfather of Achilles and Ajax, for whom Zeus turned the island's ants into the Myrmidons." }),
  c("amalthea", "Amalthea", "nymph", "🐐", "Nurse of Zeus", "f", { aliases: ["Amaltheia"], domains: ["nurture"], summary: "The foster-mother of the infant [[zeus]] in the cave on Crete, described either as a nymph who fed him on goat's milk or as the goat itself. One of the goat's horns became the [[cornucopia]], the horn of plenty. In some accounts its hide became the aegis, and Zeus placed the goat among the stars as Capella." }),
  c("galatea", "Galatea", "nymph", "🥛", "The Milk-White Nereid", "f", { aliases: ["Galateia"], summary: "A Nereid of the Sicilian sea, daughter of [[nereus]] and Doris. The Cyclops [[polyphemus]] courted her with clumsy songs, a theme popular with Theocritus. In Ovid she loves the young shepherd Acis; the jealous Polyphemus crushes him with a rock, and Galatea turns his blood into the river Acis. She is unrelated to the statue brought to life for Pygmalion." }),

  c("achelous", "Achelous", "river god", "🐂", "Greatest of the River Gods", "m", { aliases: ["Acheloos"], domains: ["the river Achelous", "fresh water"], summary: "God of the Achelous, the largest river in Greece, and eldest of the sons of [[oceanus]] and Tethys. He wrestled [[heracles]] for the hand of [[deianira]], changing into a serpent and then a bull; Heracles broke off one of his horns, which in some versions became the horn of plenty. He is often named as father of the Sirens." }),
  c("scamander", "Scamander", "river god", "🏞️", "River God of Troy", "m", { aliases: ["Xanthus", "Skamandros"], domains: ["the river Scamander"], summary: "God of the chief river of the Trojan plain, called Xanthus by the gods and Scamander by mortals. Through his grandson Tros he was an ancestor of the Trojan royal house. In Iliad 21, enraged that [[achilles]] has choked his stream with corpses, he rises to drown the hero, until [[hephaestus]] scorches his waters into submission." }),
  c("alpheus", "Alpheus", "river god", "🚿", "River God of Elis and Arcadia", "m", { aliases: ["Alpheios"], domains: ["the river Alpheus"], summary: "God of the longest river of the Peloponnese, which flows past Olympia; a son of [[oceanus]] and Tethys. He fell in love with the nymph [[arethusa]] and pursued her under the sea to Sicily, where his waters were said to rise in her spring. [[heracles]] diverted his stream to clean the stables of Augeas." }),
  c("peneus", "Peneus", "river god", "🌊", "River God of Thessaly", "m", { aliases: ["Peneios"], domains: ["the river Peneus"], summary: "God of the principal river of Thessaly, which runs through the Vale of Tempe; a son of [[oceanus]] and Tethys. He was father of [[daphne]], whom in Ovid's telling he transformed into a laurel to save her from Apollo, and of Hypseus, king of the Lapiths, and so grandfather of the nymph Cyrene." }),
  c("inachus", "Inachus", "river god", "🏞️", "River God and First King of Argos", "m", { aliases: ["Inachos"], domains: ["the river Inachus"], summary: "God of the river of the Argive plain, son of [[oceanus]] and Tethys, and in local tradition the first king of [[argos]]. He was father of [[io]] and of Phoroneus. When he judged the land to belong to Hera rather than Poseidon, the sea god dried up his stream, which thereafter ran only after rain." }),
  c("asopus", "Asopus", "river god", "🏞️", "River God of Boeotia and Sicyon", "m", { aliases: ["Asopos"], domains: ["the river Asopus"], summary: "God of two rivers of the same name, in Boeotia and near Sicyon. By Metope he had many daughters who gave their names to cities and islands, among them [[aegina]], Thebe and Salamis. When Zeus abducted Aegina, [[sisyphus]] told Asopus the culprit in exchange for a spring on the Corinthian acropolis; Zeus drove the pursuing river back with thunderbolts." }),
];
